def valid_date(date_str):
    """Validates a given date string according to the specified rules."""

    # Check if the input string is empty
    if not date_str:
        return False

    # Split the input string into month, day, and year components
    try:
        month, day, year = map(int, date_str.split('-'))
    except ValueError:
        return False

    # Validate the month and day based on the rules provided
    if month < 1 or month > 12:
        return False
    elif month in [1, 3, 5, 7, 8, 10, 12] and (day < 1 or day > 31):
        return False
    elif month in [4, 6, 9, 11] and (day < 1 or day > 30):
        return False
    elif month == 2 and (day < 1 or day > 29):
        return False

    # Check if the year is within the valid range (1800 to 2100)
    if year < 1800 or year > 2100:
        return False

    # If all checks pass, the date is valid
    return True

