def tri(n):
    # Base cases for the first three terms of the sequence
    if n == 0:
        return []
    elif n == 1:
        return [1]
    elif n == 2:
        return [1, 3]

    # Initialize the first three terms of the sequence
    sequence = [1, 3, 2]

    # Calculate the rest of the sequence using the recurrence relation
    while len(sequence) < n + 1:
        next_term = sequence[-1] + sequence[-2] + sequence[-3]
        sequence.append(next_term)

    return sequence

from typing import List
def match_parens(lst: List[str]) -> str:
    """
    Check if concatenating two strings from the given list in any order will result in a valid parentheses string.

    Args:
        lst (List[str]): A list containing two strings consisting only of '(' and ')'.

    Returns:
        str: 'Yes' if concatenating in any order results in a valid parentheses string, 'No' otherwise.
    """
    def is_valid(s: str) -> bool:
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    first_str = lst[0]
    second_str = lst[1]

    # Check both possible concatenations
    if is_valid(first_str + second_str) or is_valid(second_str + first_str):
        return 'Yes'
    else:
        return 'No'

