def is_nested(string):
    stack = []

    # Iterate over each character in the string
    for char in string:
        # If an opening bracket is encountered, push it onto the stack
        if char == '[':
            stack.append(char)
        # If a closing bracket is encountered
        elif char == ']':
            # Check if the stack is not empty and the last element on the stack is an opening bracket
            if stack and stack[-1] == '[':
                stack.pop()  # Pop the last element from the stack (indicating matching opening bracket)
            else:
                return False  # No matching opening bracket found

    # If the stack is empty, all brackets have been matched properly; otherwise, there's an unpaired closing bracket
    return len(stack) == 0

