def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.

    :param arr: List of integers
    :return: Number of elements with positive digit sums
    """
    def digit_sum(n):
        """Helper function to calculate the sum of digits of an integer"""
        if n < 0:
            return digit_sum(-n)
        return sum(int(digit) for digit in str(n))

    # Filter the array based on the condition and count the valid numbers
    valid_numbers = [num for num in arr if digit_sum(num) > 0]
    return len(valid_numbers)

def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores,
    and if a string has more than 2 consecutive spaces, then replace all consecutive spaces with -

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    result = []
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count > 2:
                result.append('-' * space_count)
            elif space_count > 0:
                result.append('_' * space_count)
            space_count = 0
            result.append(char)

    # Add the last sequence of spaces or characters
    if space_count > 2:
        result.append('-' * space_count)
    elif space_count > 0:
        result.append('_' * space_count)

    return ''.join(result)

