def prod_signs(arr: List[int]) -> int:
    if not arr:
        return None

    product_of_signs = 1
    sum_of_magnitudes = 0

    for num in arr:
        product_of_signs *= (-1)**num  # Multiply product of signs by the sign of the current number

        if num != 0:
            sum_of_magnitudes += abs(num)  # Add the absolute value of the current number to the sum of magnitudes

    return product_of_signs * sum_of_magnitudes

