def find_solution(a, b, n):
    # Check if there's no solution when gcd(a, b) != 1
    if gcd(a, b) != 1:
        return None

    # Calculate the modular multiplicative inverse of b modulo a
    inv_b = pow(b, -1, a)

    # Calculate the values of x and y using the formula derived from the extended Euclidean algorithm
    x = (n * inv_b) % a
    y = (a * (b * inv_b)) // n

    return (x, y)

