def lps(s):
    n = len(s)

    # Create a 2D array dp where dp[i][j] will be the length of the longest palindromic subsequence in s[i:j+1]
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Base case: single character palindromes have length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the dp array in bottom-up manner
    for length in range(2, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            if s[start] == s[end]:
                dp[start][end] = 2 + dp[start + 1][end - 1]
            else:
                dp[start][end] = max(dp[start + 1][end], dp[start][end - 1])

    return dp[0][n - 1]

