def amicable_numbers_sum(n):
    def get_divisors(x):
        """Helper function to find divisors of a number"""
        divisors = []
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                divisors.append(i)
                if i != x // i:
                    divisors.append(x // i)
        return divisors

    amicable_pairs = []
    # Check each number from 1 to n
    for num in range(1, n + 1):
        divs = get_divisors(num)
        # Calculate the sum of divisors excluding the number itself
        divisors_sum = sum(divs) - num
        # Check if the calculated sum is equal to the original number (amicable pair)
        if divisors_sum != num and divisors_sum in divs:
            amicable_pairs.append((num, divisors_sum))

    # Sum all amicable pairs found
    return sum(sum(pair) for pair in amicable_pairs)

